INSERT INTO "InterviewQuestion" (
  "id", "round", "kind", "level", "topic", "prompt", "domainTags", "options", "answerIndex",
  "modelAnswer", "explanation", "starterCode", "language", "hints", "minutes", "isActive", "isSample",
  "createdAt", "updatedAt"
) VALUES
  ('apt-quant-01', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Speed, time & distance', 'A train 150 metres long crosses an electric pole in 15 seconds. What is its speed?', ARRAY[]::text[], ARRAY['36 km/h', '45 km/h', '54 km/h', '60 km/h']::text[], 0, NULL, 'Crossing a pole means covering its own length: 150 ÷ 15 = 10 m/s. Multiply by 18/5 to get 36 km/h.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-quant-02', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Percentages', 'The price of a laptop is increased by 20% and then reduced by 20%. What is the net change?', ARRAY[]::text[], ARRAY['No change', '4% decrease', '4% increase', '2% decrease']::text[], 1, NULL, '1.20 × 0.80 = 0.96, so the final price is 96% of the original — a 4% decrease.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-quant-03', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Ratio & proportion', 'Two numbers are in the ratio 3 : 4 and add up to 84. What is the larger number?', ARRAY[]::text[], ARRAY['36', '42', '48', '56']::text[], 2, NULL, '3x + 4x = 84, so x = 12. The numbers are 36 and 48.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-quant-04', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Time & work', 'A finishes a job in 12 days and B in 18 days. Working together, how long do they take?', ARRAY[]::text[], ARRAY['6 days', '7.2 days', '8 days', '9 days']::text[], 1, NULL, 'Combined rate = 1/12 + 1/18 = 5/36 of the job per day, so the job takes 36/5 = 7.2 days.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-quant-05', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Averages', 'The average of five numbers is 27. If the number 35 is removed, what is the average of the rest?', ARRAY[]::text[], ARRAY['23', '25', '26', '28']::text[], 1, NULL, 'Total = 5 × 27 = 135. Without 35, the total is 100 across four numbers, so the average is 25.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-quant-06', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Compound interest', 'What is the compound interest on ₹10,000 at 10% per annum for 2 years, compounded annually?', ARRAY[]::text[], ARRAY['₹2,000', '₹2,100', '₹2,210', '₹1,900']::text[], 1, NULL, 'Amount = 10,000 × 1.1² = ₹12,100, so the interest is ₹2,100.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-quant-07', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Profit & loss', 'A shopkeeper buys an item for ₹400 and sells it at a 20% profit. What is the selling price?', ARRAY[]::text[], ARRAY['₹420', '₹440', '₹480', '₹500']::text[], 2, NULL, 'Profit = 20% of 400 = ₹80, so the selling price is ₹480.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-quant-08', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Average speed', 'A car covers 60 km at 30 km/h and returns along the same route at 60 km/h. What is the average speed for the whole trip?', ARRAY[]::text[], ARRAY['40 km/h', '45 km/h', '48 km/h', '50 km/h']::text[], 0, NULL, 'Average speed = 2ab/(a+b) = (2 × 30 × 60)/90 = 40 km/h. It is not the plain average of the two speeds.', NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('apt-quant-09', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Probability', 'A fair die is rolled twice. What is the probability that the two rolls add up to 8?', ARRAY[]::text[], ARRAY['1/6', '5/36', '1/9', '7/36']::text[], 1, NULL, 'The pairs are (2,6), (3,5), (4,4), (5,3) and (6,2) — 5 outcomes out of 36.', NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('apt-quant-10', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Permutations', 'How many distinct arrangements can be made from the letters of the word LEVEL?', ARRAY[]::text[], ARRAY['20', '30', '60', '120']::text[], 1, NULL, '5 letters with L twice and E twice: 5!/(2! × 2!) = 120/4 = 30.', NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('apt-quant-11', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Number system', 'What is the highest common factor (HCF) of 36 and 60?', ARRAY[]::text[], ARRAY['6', '12', '18', '24']::text[], 1, NULL, '36 = 2² × 3², 60 = 2² × 3 × 5. Common factors: 2² × 3 = 12.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-quant-12', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Ages', 'A father is three times as old as his son. In 12 years he will be twice as old. How old is the father now?', ARRAY[]::text[], ARRAY['30', '36', '40', '45']::text[], 1, NULL, 'If the son is s, then 3s + 12 = 2(s + 12), so s = 12 and the father is 36.', NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('apt-logic-01', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Number series', 'Find the next number: 2, 6, 12, 20, 30, ?', ARRAY[]::text[], ARRAY['36', '40', '42', '44']::text[], 2, NULL, 'The gaps are 4, 6, 8, 10, so the next gap is 12: 30 + 12 = 42.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-logic-02', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Number series', 'Find the next number: 3, 9, 27, 81, ?', ARRAY[]::text[], ARRAY['162', '216', '243', '324']::text[], 2, NULL, 'Each term is multiplied by 3, so 81 × 3 = 243.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-logic-03', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Odd one out', 'Which one does not belong: 121, 144, 169, 200?', ARRAY[]::text[], ARRAY['121', '144', '169', '200']::text[], 3, NULL, '121 = 11², 144 = 12², 169 = 13². 200 is not a perfect square.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-logic-04', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Coding & decoding', 'If FACE is written as GBDF, how is BOOK written in the same code?', ARRAY[]::text[], ARRAY['CPPL', 'CPLP', 'BPPL', 'CPPK']::text[], 0, NULL, 'Each letter moves one step forward: B→C, O→P, O→P, K→L.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-logic-05', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Blood relations', 'Pointing at a photograph, Raj says, “He is the son of my father''s only son.” Who is in the photograph?', ARRAY[]::text[], ARRAY['Raj''s brother', 'Raj''s son', 'Raj''s father', 'Raj''s nephew']::text[], 1, NULL, 'His father''s only son is Raj himself, so the photograph shows Raj''s son.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-logic-06', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Directions', 'Ravi walks 5 km north, turns right and walks 3 km, then turns right again and walks 5 km. How far is he from his starting point?', ARRAY[]::text[], ARRAY['3 km', '5 km', '8 km', '13 km']::text[], 0, NULL, 'The two 5 km legs cancel out (north then south), leaving him 3 km east of where he started.', NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('apt-logic-07', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Syllogisms', 'All roses are flowers. Some flowers fade quickly. Which conclusion definitely follows?', ARRAY[]::text[], ARRAY['Some roses fade quickly', 'No rose fades quickly', 'All flowers are roses', 'Neither conclusion definitely follows']::text[], 3, NULL, 'The flowers that fade quickly may be entirely outside the set of roses, so nothing definite follows about roses.', NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('apt-logic-08', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Analogies', 'Doctor : Patient :: Teacher : ?', ARRAY[]::text[], ARRAY['School', 'Student', 'Book', 'Lesson']::text[], 1, NULL, 'A doctor serves a patient just as a teacher serves a student.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-logic-09', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Calendars', 'If 1 January 2024 is a Monday, what day is 1 February 2024?', ARRAY[]::text[], ARRAY['Wednesday', 'Thursday', 'Friday', 'Saturday']::text[], 1, NULL, 'January has 31 days; 31 ÷ 7 leaves 3. Monday + 3 days = Thursday.', NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('apt-logic-10', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Clocks', 'What is the angle between the hands of a clock at 3:30?', ARRAY[]::text[], ARRAY['60°', '75°', '80°', '90°']::text[], 1, NULL, 'Angle = |30H − 5.5M| = |90 − 165| = 75°.', NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('apt-verbal-01', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Synonyms', 'Choose the word closest in meaning to “meticulous”.', ARRAY[]::text[], ARRAY['Careless', 'Careful', 'Generous', 'Hesitant']::text[], 1, NULL, 'Meticulous means showing great attention to detail — careful.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-verbal-02', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Antonyms', 'Choose the word opposite in meaning to “scarce”.', ARRAY[]::text[], ARRAY['Rare', 'Limited', 'Abundant', 'Costly']::text[], 2, NULL, 'Scarce means in short supply; abundant means plentiful.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-verbal-03', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Grammar', 'Which sentence is correct?', ARRAY[]::text[], ARRAY['He is one of the best player in the team.', 'He is one of the best players in the team.', 'He is one of the better player in the team.', 'He is one of best players in team.']::text[], 1, NULL, '“One of the …” is always followed by a plural noun: one of the best players.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-verbal-04', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Vocabulary in context', 'The manager was ___ about the delay and apologised to every client personally.', ARRAY[]::text[], ARRAY['indifferent', 'apologetic', 'delighted', 'evasive']::text[], 1, NULL, 'Apologising to every client shows he was apologetic.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-verbal-05', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Idioms', 'What does the idiom “bite the bullet” mean?', ARRAY[]::text[], ARRAY['To face something difficult with courage', 'To speak without thinking', 'To waste an opportunity', 'To argue stubbornly']::text[], 0, NULL, 'It means to accept something unpleasant and get on with it.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-verbal-06', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Error spotting', 'Find the error: “Each of the students have submitted the assignment on time.”', ARRAY[]::text[], ARRAY['Each of', 'the students', 'have submitted', 'on time']::text[], 2, NULL, '“Each” is singular, so it takes “has submitted”.', NULL, NULL, ARRAY[]::text[], 2, true, false, now(), now()),
  ('apt-verbal-07', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Spelling', 'Which word is spelled correctly?', ARRAY[]::text[], ARRAY['Occurence', 'Ocurrence', 'Occurrence', 'Occurrance']::text[], 2, NULL, 'Occurrence has double c and double r.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('apt-verbal-08', 'APTITUDE'::"InterviewRound", 'MCQ'::"InterviewKind", 'BEGINNER'::"Level", 'Prepositions', 'She has been working at this company ___ 2019.', ARRAY[]::text[], ARRAY['from', 'since', 'for', 'during']::text[], 1, NULL, '“Since” is used with a point in time; “for” would need a duration, such as “for six years”.', NULL, NULL, ARRAY[]::text[], 1, true, false, now(), now()),
  ('tech-cyber-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Security fundamentals', 'What is the CIA triad, and can you give a real example of a control that protects each part?', ARRAY['cybersecurity']::text[], ARRAY[]::text[], NULL, 'Confidentiality, Integrity and Availability. Confidentiality keeps data secret — encryption at rest and in transit, least-privilege access, MFA. Integrity keeps data correct and unaltered — hashing, digital signatures, change control, file integrity monitoring. Availability keeps systems usable — backups, redundancy, DDoS protection, patching. A strong answer notes the trade-offs: heavy controls on confidentiality can hurt availability.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-cyber-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Networking', 'Explain the difference between TCP and UDP, and walk me through the TCP three-way handshake.', ARRAY['cybersecurity', '5g-technology']::text[], ARRAY[]::text[], NULL, 'TCP is connection-oriented and reliable: ordered delivery, retransmission, flow and congestion control — used for HTTP, SSH, email. UDP is connectionless with no delivery guarantee, so it is faster and used for DNS, VoIP, video and gaming. The handshake: client sends SYN with its sequence number, server replies SYN-ACK acknowledging it and sending its own, client sends ACK. Teardown uses FIN/ACK. Mentioning SYN floods and why they work shows depth.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-cyber-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Cryptography', 'When would you use symmetric encryption versus asymmetric encryption? How does HTTPS use both?', ARRAY['cybersecurity', 'blockchain']::text[], ARRAY[]::text[], NULL, 'Symmetric (AES) uses one shared key: fast, good for bulk data, but key distribution is the problem. Asymmetric (RSA, ECC) uses a public/private key pair: solves key exchange and enables signatures, but is slow. HTTPS uses both — the TLS handshake authenticates the server with its certificate and agrees a shared secret (today usually ECDHE, giving forward secrecy), then the session itself is encrypted symmetrically with AES-GCM or ChaCha20. Hashing (SHA-256) covers integrity.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-cyber-04', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Incident response', 'A user reports a suspicious email and says they clicked the link. Walk me through your triage.', ARRAY['cybersecurity']::text[], ARRAY[]::text[], NULL, 'Contain first: isolate the host if there are signs of execution, reset the user''s credentials and revoke sessions. Collect evidence: the full email with headers, the URL and any attachment hashes, proxy and EDR logs for that host and user. Analyse in a safe environment or with threat intel — is the domain known bad, was a payload downloaded, did credentials get submitted? Scope it: search mail logs for the same sender or URL across the organisation and pull those messages. Eradicate and recover, then close the loop: block the indicators, note detection gaps, tell the user what happened without blaming them.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-cyber-05', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Detection engineering', 'How would you tell a true positive from a false positive when an alert fires for PowerShell spawned by Word?', ARRAY['cybersecurity']::text[], ARRAY[]::text[], NULL, 'Look at the process tree and the command line: encoded commands, download cradles or references to remote URLs are strong signals. Check the parent document, where it came from and whether the user expected it. Correlate with network connections from that host, new persistence (run keys, scheduled tasks) and any child processes. Compare against a baseline — some finance or macro-heavy teams legitimately run scripts. Tune the rule with allowlists based on signed macros or specific paths rather than switching it off, and note the MITRE ATT&CK technique (T1059.001) for tracking.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-hack-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Web vulnerabilities', 'Explain SQL injection to a developer, and tell them exactly how to fix it.', ARRAY['ethical-hacking', 'cybersecurity', 'full-stack']::text[], ARRAY[]::text[], NULL, 'User input is concatenated into a SQL statement, so the input can change the query''s meaning — reading other users'' rows, bypassing login, or dumping tables. The fix is parameterised queries or prepared statements, where the query structure is fixed and input is only ever data. Supporting measures: an ORM used correctly, least-privilege database accounts, input validation and allowlists for things like sort columns that can''t be parameterised, and WAF rules as a stopgap. Escaping by hand is not a reliable fix.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-hack-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Methodology', 'What is the difference between a vulnerability scan and a penetration test? When is each appropriate?', ARRAY['ethical-hacking']::text[], ARRAY[]::text[], NULL, 'A vulnerability scan is automated, broad and mostly signature-based: it lists known weaknesses with little context, is cheap, and suits continuous monthly or weekly coverage. A penetration test is human-led: it chains findings, tests business logic and access control that scanners miss, proves real impact, and produces prioritised, contextual recommendations — but it costs more and is point-in-time. Scans for routine hygiene and compliance; pentests before launches, after major changes, or annually for certification. Mentioning scope, rules of engagement and safe harbour earns extra credit.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-hack-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'ADVANCED'::"Level", 'Privilege escalation', 'You have a low-privileged shell on a Linux host. How do you look for a path to root?', ARRAY['ethical-hacking']::text[], ARRAY[]::text[], NULL, 'Enumerate systematically: kernel and distribution version against known exploits; sudo -l for allowed commands and GTFOBins tricks; SUID/SGID binaries; writable files, scripts and directories in PATH; cron jobs running as root; capabilities; running services on localhost; credentials in config files, history and environment variables; group memberships such as docker, lxd or disk. Automate the sweep with LinPEAS but verify by hand. Pick the quietest reliable path, document each step for the report, and avoid anything that risks stability on a production host.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-ml-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Model fundamentals', 'What is overfitting? How do you detect it and what do you do about it?', ARRAY['ai-ml']::text[], ARRAY[]::text[], NULL, 'The model learns noise specific to the training set, so training error keeps falling while validation error rises. Detect it by holding out validation data, watching the gap between training and validation metrics, and using cross-validation. Fixes: more or better data, augmentation, simpler models or fewer features, regularisation (L1/L2, dropout, early stopping), and cross-validated hyperparameter tuning. Also check for leakage, which looks like great validation scores and poor production performance.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-ml-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Evaluation', 'Precision or recall — which would you optimise for a fraud detection model, and why?', ARRAY['ai-ml', 'data-analysis']::text[], ARRAY[]::text[], NULL, 'Recall matters more when missing a fraudulent transaction is costlier than reviewing a legitimate one, which is usually the case; but precision protects customer experience and analyst time. In practice you pick a threshold from the precision-recall curve to meet a business constraint — for example the maximum number of cases a review team can handle per day. Accuracy is useless here because the classes are heavily imbalanced. Mention PR-AUC over ROC-AUC for rare positives, and the cost matrix behind the decision.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-ml-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Training', 'Explain gradient descent, and what learning rate and batch size actually change.', ARRAY['ai-ml']::text[], ARRAY[]::text[], NULL, 'Gradient descent updates parameters in the direction that reduces the loss, step size set by the learning rate. Too high and training diverges or oscillates; too low and it crawls or gets stuck — hence schedules and warm-up. Batch size sets how many samples the gradient is estimated from: small batches are noisy but regularise and fit in memory; large batches are smoother and faster per epoch but can generalise worse and need a scaled learning rate. Variants like SGD with momentum, Adam and AdamW adapt the step per parameter.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-ml-04', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Data splits', 'What is data leakage, and how do you prevent it in a time-series problem?', ARRAY['ai-ml', 'data-engineering']::text[], ARRAY[]::text[], NULL, 'Leakage is when information unavailable at prediction time slips into training, so offline scores look great and production fails. Classic causes: scaling or imputing before the split, target-derived features, duplicate rows across splits, and using future data. For time series, split chronologically rather than randomly, use walk-forward or rolling-origin validation, compute rolling features only from past windows, and respect any reporting lag in the source data. Fit all preprocessing inside the training fold, ideally in a pipeline.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-ml-05', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'ADVANCED'::"Level", 'LLM applications', 'A RAG chatbot keeps answering from the wrong document. How do you debug and improve it?', ARRAY['ai-ml']::text[], ARRAY[]::text[], NULL, 'Separate retrieval from generation. Measure retrieval alone: for a labelled set of questions, is the right chunk in the top-k? If not, the problem is chunking (size, overlap, splitting mid-section), the embedding model, missing metadata filters, or the query itself — try query rewriting, hybrid keyword plus vector search, and a reranker. If retrieval is right but answers are wrong, fix the prompt: instruct the model to answer only from context, require citations, and handle ''not in the documents''. Add an eval set with scores you track per change, and log retrieved chunks in production so failures are reproducible.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-da-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'SQL joins', 'Explain the difference between an INNER JOIN and a LEFT JOIN, with an example where the choice changes the answer.', ARRAY['data-analysis', 'data-engineering']::text[], ARRAY[]::text[], NULL, 'INNER JOIN keeps only rows that match in both tables; LEFT JOIN keeps every row from the left table and fills unmatched right-hand columns with NULL. Counting orders per customer with an INNER JOIN silently drops customers with zero orders, understating the customer count; a LEFT JOIN keeps them and COUNT of the order id returns 0. A common trap is putting a filter on the right table in the WHERE clause, which turns a LEFT JOIN back into an inner join — that condition belongs in the ON clause.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-da-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'SQL window functions', 'Give a business question you would answer with a window function, and explain how it works.', ARRAY['data-analysis', 'data-engineering']::text[], ARRAY[]::text[], NULL, 'Examples: rank products by revenue within each region, month-over-month growth with LAG, a running total of daily sales, or each customer''s most recent order. A window function computes across a set of rows related to the current row without collapsing them, unlike GROUP BY: PARTITION BY defines the group, ORDER BY the sequence, and the frame clause the sliding window. So ROW_NUMBER() OVER (PARTITION BY region ORDER BY revenue DESC) numbers products inside each region while keeping every row visible.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-da-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Data cleaning', 'A dataset has 15% missing values in an important column. What do you do?', ARRAY['data-analysis']::text[], ARRAY[]::text[], NULL, 'First understand why they are missing — random, or related to something systematic like a form field added later or a sensor failure, because that decides what is safe. Options: drop rows only if few and missing at random; impute with median or mode for simple cases, or a model-based or grouped imputation when the column matters; add a ''was missing'' indicator so the model can use that signal; or treat missing as its own category for categorical data. Whatever you choose, document it, apply it inside the pipeline so it can''t leak, and check how much the result changes under different choices.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-da-04', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Statistics', 'Explain a p-value to a marketing manager who has no statistics background.', ARRAY['data-analysis', 'ai-ml']::text[], ARRAY[]::text[], NULL, 'It answers: if the change really did nothing, how often would we see a result at least this big just by chance? A small p-value (say under 0.05) means the result would be unlikely from luck alone, so we treat it as real. It does not tell you the probability the change works, nor how big the effect is — pair it with the effect size and a confidence interval. Watch out for peeking at results early, testing many variants and small samples, all of which produce convincing-looking noise.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-da-05', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Dashboards', 'A sales head asks for “a dashboard with everything”. How do you handle it?', ARRAY['data-analysis']::text[], ARRAY[]::text[], NULL, 'Push back gently and start with decisions, not charts: what will you do differently depending on what this shows? Agree on three to five metrics tied to those decisions, their exact definitions and grain, and who looks at it how often. Design top-down — headline numbers with comparisons against target or last period, then a small number of breakdowns, then detail on drill-through. Keep one chart per question, label clearly, show data freshness, and agree what happens when a number looks wrong. Ship a small version, watch it being used, then iterate.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-de-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Pipeline design', 'When would you choose batch processing over streaming, and what does streaming cost you?', ARRAY['data-engineering']::text[], ARRAY[]::text[], NULL, 'Batch suits work where minutes or hours of latency are fine: daily reporting, model training sets, heavy joins and backfills. It is simpler to test, cheaper, and easy to re-run. Streaming is for cases where the value decays fast — fraud checks, live dashboards, alerting. The cost is complexity: out-of-order and late events, watermarks, exactly-once semantics, state stores, harder testing and debugging, and always-on infrastructure. Many teams run a hybrid: streaming for the freshness-critical slice, batch for correctness and reprocessing.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-de-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Modelling', 'Why do analytics warehouses use star schemas instead of the normalised model an application uses?', ARRAY['data-engineering', 'data-analysis']::text[], ARRAY[]::text[], NULL, 'Application databases normalise to avoid update anomalies and keep writes cheap. Warehouses are read-heavy, so a star schema — a fact table of events with foreign keys to descriptive dimension tables — means fewer joins, simpler queries for analysts, and better use of columnar storage and partition pruning. Dimensions are deliberately denormalised and use surrogate keys, with slowly changing dimension handling (usually type 2) so history is preserved. Mentioning grain — one row per what — is the sign of someone who has actually modelled data.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-de-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Reliability', 'What does it mean for a pipeline to be idempotent, and how do you build one?', ARRAY['data-engineering']::text[], ARRAY[]::text[], NULL, 'Running it twice with the same input leaves the same result — essential because retries, backfills and partial failures are normal. Techniques: write to a partition keyed by the run''s logical date and overwrite it rather than appending; use MERGE or upserts on a natural key; stage output and swap atomically; deduplicate on an event id; make downstream consumers tolerant of replays. Avoid ''insert whatever arrived since last time'' with no key, and avoid side effects such as emails that cannot be undone on retry.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-de-04', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Storage & performance', 'A Spark job over Parquet in cloud storage is slow. What do you look at?', ARRAY['data-engineering']::text[], ARRAY[]::text[], NULL, 'Check the data layout first: too many small files, or a few huge ones, both hurt — compact to a sensible file size and partition on a column that actually filters queries, without over-partitioning. Then the query: push filters and column pruning down, avoid wide shuffles and cartesian joins, broadcast the small side of a join, and look for skew on hot keys (salting or adaptive execution helps). Check the Spark UI for stage-level spill, GC time and straggler tasks, and confirm the cluster is not simply under-resourced or throttled by storage.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-de-05', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'ADVANCED'::"Level", 'Data quality', 'An upstream team changes a column''s meaning without telling you. How do you stop this hurting dashboards?', ARRAY['data-engineering', 'data-analysis']::text[], ARRAY[]::text[], NULL, 'Treat the interface as a contract: agreed schema, types, nullability and semantics, versioned and checked in CI. Add tests at ingestion — schema checks, null and range expectations, accepted values, row-count and distribution drift — and fail or quarantine rather than silently loading. Track lineage so you can see which dashboards depend on the column, alert the owning team and consumers, and keep raw data immutable so you can reprocess once the meaning is clear. Longer term, agree change notification and deprecation windows with upstream owners.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-cloud-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Cloud basics', 'Explain IaaS, PaaS and SaaS with an example of each, and who is responsible for what.', ARRAY['cloud-computing']::text[], ARRAY[]::text[], NULL, 'IaaS gives raw building blocks — EC2, virtual networks, disks — and you manage the OS, runtime, patching and scaling. PaaS gives a managed platform such as App Service, App Engine or RDS: you bring code or data, the provider handles the OS and much of the operations. SaaS is finished software like Gmail or Salesforce, where you only manage users and data. The shared responsibility model is the thread running through it: the provider secures the cloud, you secure what you put in it — your data, identities and configuration — at every level.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-cloud-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'High availability', 'What is the difference between a region and an availability zone, and how does that shape a highly available design?', ARRAY['cloud-computing']::text[], ARRAY[]::text[], NULL, 'A region is a geographic location; an availability zone is an isolated datacentre (or group) within it, with independent power and cooling but low-latency links to its siblings. Standard HA: run instances in at least two AZs behind a load balancer, use multi-AZ managed databases with automatic failover, and keep state outside the instances in object storage or a managed store. Multi-region is for disaster recovery or global latency and costs much more — decide with an explicit RTO and RPO, and test failover rather than assuming it works.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-cloud-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Identity', 'How would you apply least privilege in a cloud account where developers keep asking for admin?', ARRAY['cloud-computing', 'cybersecurity']::text[], ARRAY[]::text[], NULL, 'Start from roles, not people: define job-function roles with only the permissions their work needs, and attach them to groups. Give applications workload identities or instance roles rather than long-lived keys. Use temporary elevation with approval and an expiry for the rare admin task, and log it. Separate environments into different accounts, projects or subscriptions so a mistake in dev cannot touch production. Use the provider''s access analyser and unused-permission reports to trim over time, and guardrails (SCPs, Azure Policy, org policies) to make dangerous actions impossible rather than merely discouraged.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-cloud-04', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Scaling', 'Traffic to a web app triples every evening. How do you handle it without paying for peak capacity all day?', ARRAY['cloud-computing']::text[], ARRAY[]::text[], NULL, 'Horizontal autoscaling behind a load balancer, driven by a signal that tracks user pain — request concurrency or latency, not just CPU. Set sensible minimums so a cold start does not meet the spike, use scheduled scaling for a known evening pattern, and keep instances stateless so they can come and go. Cache aggressively: CDN for static assets, application cache for hot reads, and connection pooling so the database is not the bottleneck. Queue work that does not need to be synchronous. Watch scale-in policies so you do not flap, and load test the pattern before it matters.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-cloud-05', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'ADVANCED'::"Level", 'Cost', 'Your cloud bill doubled this quarter. Walk me through finding out why and fixing it.', ARRAY['cloud-computing']::text[], ARRAY[]::text[], NULL, 'Get visibility first: cost explorer grouped by service, account and tag, comparing against last quarter to find the delta rather than the biggest line. Usual culprits: idle or oversized instances, forgotten environments, storage class and snapshot sprawl, cross-AZ or egress traffic, logging volume, and a new feature''s query pattern. Fix in order of effort: kill waste, right-size, move cold data to cheaper tiers, add autoscaling and schedules for non-production, then commit to savings plans or reserved capacity for the steady baseline. Prevent recurrence with tagging standards, budgets and alerts, and showback to the teams that spend.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-fs-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'API design', 'Design the REST endpoints for a blog with posts and comments. Which status codes do you return?', ARRAY['full-stack']::text[], ARRAY[]::text[], NULL, 'Nouns and plurals: GET /posts (list, paginated), POST /posts (create), GET /posts/:id, PATCH /posts/:id, DELETE /posts/:id, and nested GET/POST /posts/:id/comments. Status codes: 200 for success, 201 with a Location header for creation, 204 for a delete with no body, 400 for malformed input, 401 unauthenticated, 403 authenticated but not allowed, 404 not found, 409 conflict, 422 for validation failures, 429 rate limited, 500 for server faults. Mention pagination, filtering, sorting, consistent error shapes and versioning.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-fs-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Databases', 'How do you decide between a relational database and a document store for a new product?', ARRAY['full-stack']::text[], ARRAY[]::text[], NULL, 'Start from the data and the queries. Relational fits when entities have clear relationships, you need joins, multi-row transactions and strong constraints — which is most business software, and Postgres also handles JSON when you need it. Document stores fit flexible or evolving shapes, documents read and written whole, or very high write throughput where you can design around the access pattern. The honest answer names the trade-off: schema flexibility now versus integrity and ad-hoc querying later, and that migrating data models later is expensive either way.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-fs-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Authentication', 'Sessions or JWTs for a web app? Explain the trade-off and how you store them safely.', ARRAY['full-stack', 'cybersecurity']::text[], ARRAY[]::text[], NULL, 'Server-side sessions with an opaque cookie are simpler and can be revoked instantly, at the cost of a lookup — fine for most apps, and the default choice for a browser product. JWTs are stateless and useful across services, but cannot be revoked before expiry without extra state, so you keep access tokens short-lived and pair them with refresh tokens. Either way: store the token in an HttpOnly, Secure, SameSite cookie rather than localStorage, protect against CSRF, hash passwords with bcrypt or argon2, rotate on privilege change, and never put sensitive data in a JWT payload since it is only signed, not encrypted.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-fs-04', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'React', 'A React list re-renders on every keystroke and feels sluggish. How do you diagnose and fix it?', ARRAY['full-stack']::text[], ARRAY[]::text[], NULL, 'Profile first with React DevTools to see what re-renders and why, rather than guessing. Common causes: state held too high so every keystroke re-renders the whole tree, new object or function identities passed as props each render, expensive work in the render path, and unstable keys forcing remounts. Fixes: move state down or keep the input local, memoise expensive computations, virtualise long lists, debounce the search itself, and split components so the typing path is small. Reach for memo and useCallback after measuring — they add cost and are not a blanket fix.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-fs-05', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'ADVANCED'::"Level", 'Debugging', 'Users say the app is “slow”. You have no other information. What do you do?', ARRAY['full-stack']::text[], ARRAY[]::text[], NULL, 'Turn it into something measurable: which users, which pages, when it started, and slow to first byte or slow to interact? Split the request path — network and CDN, server time, database, and the browser. Check real-user metrics (Core Web Vitals) alongside server latency percentiles, especially p95 rather than averages, and look for a deploy or data-volume change that lines up with the start. Typical culprits: N+1 queries or a missing index, unbounded payloads, render-blocking assets, oversized images, cold starts, and chatty client calls. Fix the biggest contributor, verify with the same metric, then add an alert so the regression is caught next time.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-bc-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Ethereum basics', 'What is gas, and what practical things make a contract cheaper to use?', ARRAY['blockchain']::text[], ARRAY[]::text[], NULL, 'Gas prices the computation and storage a transaction consumes, paid in ETH; the fee is gas used times gas price, so wasteful code costs users real money. Cheaper contracts: minimise storage writes (by far the costliest operation) and read into memory first, pack variables into the same storage slot, use calldata for read-only arguments, avoid unbounded loops over arrays, emit events instead of storing data only needed off-chain, and use immutable or constant where possible. Batching and layer-2 deployment help more than micro-optimisation for most apps.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-bc-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Smart contract security', 'Explain a reentrancy attack and the ways to prevent it.', ARRAY['blockchain', 'ethical-hacking']::text[], ARRAY[]::text[], NULL, 'If a contract sends ETH (or calls an external contract) before updating its own state, the receiving contract''s fallback can call back in and repeat the withdrawal while the balance still looks unspent — the DAO hack. Prevention: checks-effects-interactions, so state is updated before the external call; a reentrancy guard such as OpenZeppelin''s nonReentrant; preferring pull payments over push; and being careful with cross-function and read-only reentrancy, where a view function is queried mid-call. Audits and invariant tests catch the cases patterns miss.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-bc-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Token standards', 'What is the difference between ERC-20, ERC-721 and ERC-1155?', ARRAY['blockchain']::text[], ARRAY[]::text[], NULL, 'ERC-20 is fungible: every unit is identical and balances are numbers — currencies, governance and utility tokens. ERC-721 is non-fungible: each token id is unique with its own owner and metadata — art, collectibles, tickets. ERC-1155 is a multi-token standard where one contract holds many token types, fungible or not, with batch transfers — efficient for games and editions. A good answer mentions approval patterns (approve/transferFrom, setApprovalForAll) and the phishing risk of unlimited approvals.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-iot-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Protocols', 'Why do IoT devices usually speak MQTT rather than plain HTTP?', ARRAY['iot']::text[], ARRAY[]::text[], NULL, 'MQTT is publish/subscribe over a long-lived TCP connection with a tiny header, so it suits constrained devices on flaky, low-bandwidth networks: no repeated connection setup, server-initiated push to devices, quality-of-service levels for delivery, retained messages and last-will notifications when a device drops. HTTP is request/response, heavier per message, and awkward for pushing commands down to a device behind NAT. HTTP still makes sense for firmware downloads and occasional large payloads, so many products use both.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-iot-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Power', 'A battery sensor must run for a year on a coin cell. What drives that, and what do you change?', ARRAY['iot']::text[], ARRAY[]::text[], NULL, 'Average current is what matters: the device should spend almost all its time in deep sleep at microamps, waking briefly to measure and transmit. Radio is the biggest consumer, so send less and less often — batch readings, only report on change or threshold, and shrink the payload. Choose the right radio (BLE or LoRa over Wi-Fi), lower transmit power where range allows, and cut peripheral draw with sensor duty cycling and efficient regulators. Then measure the real current profile with a power analyser instead of trusting the datasheet, and account for battery self-discharge and temperature.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-iot-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'ADVANCED'::"Level", 'Firmware updates', 'How do you design over-the-air updates so a bad release does not brick thousands of devices?', ARRAY['iot', 'cybersecurity']::text[], ARRAY[]::text[], NULL, 'Sign every image and verify the signature on-device with a key in secure storage, with rollback protection against downgrade attacks. Use A/B partitions or a bootloader that can fall back: write the new image to the spare slot, verify the checksum, boot once in trial mode and only mark it good after the device checks in. Roll out in stages — internal, then a small percentage, watching crash and check-in rates with an automatic halt — and keep a recovery path (a minimal known-good image) for the worst case. Resume interrupted downloads and never update on low battery.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-5g-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", '5G architecture', 'What is the difference between 5G non-standalone and standalone, and why does it matter?', ARRAY['5g-technology']::text[], ARRAY[]::text[], NULL, 'Non-standalone keeps the 4G EPC core and LTE anchor, adding 5G NR radio for capacity and speed — quick to deploy and how most operators started. Standalone uses the 5G core with its service-based architecture, so you get the features that actually differentiate 5G: lower latency, network slicing, edge integration, better device power saving and massive machine-type connectivity. Standalone needs core investment and device support, which is why rollouts are phased — enterprise and fixed wireless use cases usually justify it first.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-5g-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'Network slicing', 'Explain network slicing and give a use case where it earns its keep.', ARRAY['5g-technology']::text[], ARRAY[]::text[], NULL, 'Slicing runs multiple logical networks over shared physical infrastructure, each with its own performance and isolation guarantees, described by the slice identifier and enforced from RAN through transport to the core. A factory can have a low-latency, high-reliability slice for machine control that is unaffected by visitors streaming video on the public slice; a broadcaster can have a guaranteed uplink slice for live coverage at an event. It earns its keep where a customer will pay for a guarantee rather than best effort — and it demands end-to-end orchestration and per-slice assurance.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-5g-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'ADVANCED'::"Level", 'Open RAN', 'What is the CU/DU/RU split in Open RAN, and what do operators gain and lose from it?', ARRAY['5g-technology']::text[], ARRAY[]::text[], NULL, 'The base station is split into the radio unit at the antenna, the distributed unit handling real-time lower layers, and the centralised unit for higher layers — connected by open fronthaul and midhaul interfaces, with the RIC adding programmable control. The gain: multi-vendor competition, cheaper hardware, centralised pooling, and features delivered as software. The cost: integration burden moves to the operator, strict fronthaul timing and transport requirements, a larger security surface across open interfaces, and end-to-end performance that nobody owns single-handedly — which is why system integrators matter.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('tech-xr-01', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'BEGINNER'::"Level", 'Comfort', 'Why is frame rate so much more important in VR than in a normal game, and what causes discomfort?', ARRAY['ar-vr']::text[], ARRAY[]::text[], NULL, 'In VR the display is strapped to the head, so dropped frames and latency break the match between what the inner ear feels and what the eyes see — that mismatch causes nausea. Headsets target 72–120 Hz with consistent frame times; a stable 72 beats an uneven 90. Other comfort factors: never take control of the camera away from the user, avoid artificial acceleration, offer teleport or comfort-vignette locomotion options, keep UI at a comfortable focal distance, and maintain a stable horizon. Motion-to-photon latency and reprojection quality matter as much as raw frames per second.', NULL, NULL, NULL, ARRAY[]::text[], 3, true, false, now(), now()),
  ('tech-xr-02', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'INTERMEDIATE'::"Level", 'AR tracking', 'How does an AR app keep a virtual object stuck to a real table, and where does it go wrong?', ARRAY['ar-vr']::text[], ARRAY[]::text[], NULL, 'The device runs SLAM: camera frames plus IMU build a map of feature points and track the device pose within it. Plane detection fits horizontal or vertical surfaces from those points, and you attach the object to an anchor so the platform keeps correcting its pose as the map improves. It breaks on blank or shiny surfaces with no features, in poor or changing light, with fast motion and motion blur, and when the environment itself moves. Mitigations: guide the user to scan the area, fall back gracefully when tracking is lost, re-localise against saved anchors, and keep virtual content plausibly lit and shadowed so small drift is less obvious.', NULL, NULL, NULL, ARRAY[]::text[], 4, true, false, now(), now()),
  ('tech-xr-03', 'TECHNICAL'::"InterviewRound", 'SHORT_ANSWER'::"InterviewKind", 'ADVANCED'::"Level", 'Performance', 'A Quest build drops to 50 fps in a busy scene. How do you get it back to target?', ARRAY['ar-vr']::text[], ARRAY[]::text[], NULL, 'Profile before changing anything — decide whether you are CPU-bound or GPU-bound with the platform profiler. CPU side: cut draw calls by batching and instancing, reduce unique materials, limit physics and per-frame allocations that trigger garbage collection, and keep scripts off the hot path. GPU side: reduce overdraw and transparency, use mobile-friendly shaders, bake lighting instead of realtime lights, keep textures modest with compression and mipmaps, and use LODs and occlusion culling. Then platform tools: fixed foveated rendering, dynamic resolution and an appropriate MSAA level. Re-measure after each change and budget per frame rather than chasing the symptom.', NULL, NULL, NULL, ARRAY[]::text[], 5, true, false, now(), now()),
  ('code-two-sum', 'CODING'::"InterviewRound", 'CODING'::"InterviewKind", 'BEGINNER'::"Level", 'Arrays & hashing', 'Given an array of integers and a target, return the indices of the two numbers that add up to the target. Assume exactly one solution and that you may not use the same element twice.

Example: nums = [2, 7, 11, 15], target = 9 → [0, 1]

Write the function, then add a comment explaining the time and space complexity.', ARRAY['full-stack', 'ai-ml', 'cybersecurity', 'ethical-hacking', 'cloud-computing', 'blockchain', 'iot', 'ar-vr', '5g-technology', 'data-analysis', 'data-engineering', 'ai-ml']::text[], ARRAY[]::text[], NULL, 'One pass with a hash map from value to index: for each number, check whether target − number has already been seen; if so return the stored index and the current one, otherwise store the number. O(n) time, O(n) space. The brute-force double loop is O(n²) and should be mentioned as the starting point. Edge cases worth naming: negative numbers, duplicates (works because the earlier index is stored), and the fact that sorting plus two pointers loses the original indices.', NULL, 'def two_sum(nums, target):
    # your solution
    pass
', 'Any', ARRAY['What would you need to look up instantly while scanning once?', 'Store what you have seen, not what you are looking for.']::text[], 12, true, false, now(), now()),
  ('code-valid-parentheses', 'CODING'::"InterviewRound", 'CODING'::"InterviewKind", 'BEGINNER'::"Level", 'Stacks', 'Given a string containing only the characters ()[]{}, decide whether the brackets are balanced and correctly nested.

Examples: "([]{})" → true, "(]" → false, "([)]" → false.', ARRAY['full-stack', 'ai-ml', 'cybersecurity', 'ethical-hacking', 'cloud-computing', 'blockchain', 'iot', 'ar-vr', '5g-technology']::text[], ARRAY[]::text[], NULL, 'Push opening brackets onto a stack; on a closing bracket, the stack must be non-empty and its top must be the matching opener, else return false. At the end the stack must be empty. O(n) time and O(n) space. A map of closing to opening brackets keeps it short. Edge cases: empty string (true), string of only closers, odd length (can never be valid).', NULL, 'def is_valid(s):
    # your solution
    pass
', 'Any', ARRAY['Which data structure naturally matches “most recently opened”?', 'What must be true about the stack when the string ends?']::text[], 12, true, false, now(), now()),
  ('code-reverse-words', 'CODING'::"InterviewRound", 'CODING'::"InterviewKind", 'BEGINNER'::"Level", 'Strings', 'Reverse the order of words in a sentence, collapsing any extra whitespace.

Example: "  the sky   is blue " → "blue is sky the"

